#!/usr/bin/env python3
"""
Validation script for Canonical DSL v1.1 JSON output.
Checks top-level structure, hat fields, opcode formatting, and variable-name cross-references.
"""

import json
import sys
import re

# Load DSL spec v1.1 hat allowlist
VALID_HATS = [
    "event_whenflagclicked",
    "control_start_as_clone",
    "event_whenbroadcastreceived",
    "event_whenkeypressed"
]

# Opcodes used in DSL must match lowercase-with-underscore pattern
OPCODE_PATTERN = re.compile(r'^[a-z]+_[a-z]+(_[a-z]+)*$')

def load_json(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        return json.load(f)

def validate_structure(dsl):
    """Check top-level structure: must be {"scripts": [...]}"""
    errors = []
    if not isinstance(dsl, dict):
        errors.append("Root must be an object, got " + type(dsl).__name__)
        return errors
    if "scripts" not in dsl:
        errors.append("Missing required key 'scripts' at root")
        return errors
    if not isinstance(dsl["scripts"], list):
        errors.append("'scripts' must be an array, got " + type(dsl["scripts"]).__name__)
    # Check for extra keys at root (should only have 'scripts')
    extra_keys = set(dsl.keys()) - {"scripts"}
    if extra_keys:
        errors.append(f"Extra keys at root: {extra_keys}")
    return errors

def validate_script_object(script, index, all_hat_ids):
    """Validate a single script object."""
    errors = []

    # Required fields
    for field in ["hat", "hatId", "blocks"]:
        if field not in script:
            errors.append(f"Script[{index}]: missing required field '{field}'")

    if "hat" in script:
        if script["hat"] not in VALID_HATS:
            errors.append(f"Script[{index}]: invalid hat '{script['hat']}' (not in allowlist)")

    if "hatId" in script:
        hat_id = script["hatId"]
        if not hat_id or not isinstance(hat_id, str):
            errors.append(f"Script[{index}]: hatId must be non-empty string")
        elif hat_id in all_hat_ids:
            errors.append(f"Script[{index}]: duplicate hatId '{hat_id}'")
        else:
            all_hat_ids.add(hat_id)

    if "blocks" in script and isinstance(script["blocks"], list):
        block_errors = validate_blocks(script["blocks"], index, set())
        errors.extend(block_errors)

    return errors

def validate_blocks(blocks, script_index, allowed_substack_contexts):
    """Recursively validate blocks and substacks."""
    errors = []
    for i, block in enumerate(blocks):
        if not isinstance(block, dict):
            errors.append(f"Script[{script_index}].blocks[{i}]: block must be an object")
            continue

        opcode = block.get("opcode", "")

        # Check opcode format
        if opcode and not OPCODE_PATTERN.match(opcode):
            errors.append(f"Script[{script_index}].blocks[{i}]: opcode '{opcode}' doesn't match lowercase-with-underscore pattern")

        # Validate opcode inputs/fields based on expected schema
        if opcode == "control_forever":
            if "inputs" not in block or "SUBSTACK" not in block.get("inputs", {}):
                errors.append(f"Script[{script_index}].blocks[{i}]: 'control_forever' requires 'inputs.SUBSTACK'")
            else:
                substack = block["inputs"]["SUBSTACK"]
                if not isinstance(substack, list):
                    errors.append(f"Script[{script_index}].blocks[{i}]: 'SUBSTACK' must be an array")
                else:
                    sub_errors = validate_blocks(substack, script_index, allowed_substack_contexts | {(script_index, i)})
                    errors.extend(sub_errors)

        elif opcode == "control_if":
            if "inputs" not in block:
                errors.append(f"Script[{script_index}].blocks[{i}]: 'control_if' requires 'inputs'")
            else:
                inputs = block["inputs"]
                if "CONDITION" not in inputs:
                    errors.append(f"Script[{script_index}].blocks[{i}]: 'control_if' requires 'inputs.CONDITION'")
                elif not isinstance(inputs["CONDITION"], dict):
                    errors.append(f"Script[{script_index}].blocks[{i}]: 'CONDITION' must be a block object")
                if "SUBSTACK" not in inputs:
                    errors.append(f"Script[{script_index}].blocks[{i}]: 'control_if' requires 'inputs.SUBSTACK'")
                elif not isinstance(inputs["SUBSTACK"], list):
                    errors.append(f"Script[{script_index}].blocks[{i}]: 'SUBSTACK' must be an array")
                else:
                    sub_errors = validate_blocks(inputs["SUBSTACK"], script_index, allowed_substack_contexts | {(script_index, i)})
                    errors.extend(sub_errors)

    return errors

def validate_variable_names(dsl, metadata_vars):
    """Cross-reference variable names against project_metadata.json."""
    errors = []
    warnings = []

    # Build set of valid variable names from metadata
    valid_var_names = {v["name"] for v in metadata_vars}

    # Find all VARIABLE fields in the DSL
    def collect_variable_names(obj, path=""):
        names = []
        if isinstance(obj, dict):
            if "fields" in obj and "VARIABLE" in obj["fields"]:
                names.append(obj["fields"]["VARIABLE"])
            for key, value in obj.items():
                names.extend(collect_variable_names(value, f"{path}.{key}"))
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                names.extend(collect_variable_names(item, f"{path}[{i}]"))
        return names

    all_var_names = collect_variable_names(dsl)

    # Check each found variable name
    for var_name in set(all_var_names):
        if var_name not in valid_var_names:
            # Check if it's a local variable (prefixed with _)
            if var_name.startswith("_"):
                warnings.append(f"Variable '{var_name}' is a local variable (starts with '_'), not in metadata")
            else:
                errors.append(f"Variable '{var_name}' not found in project_metadata.json. Valid names: {valid_var_names}")

    return errors, warnings

def main():
    # File paths
    dsl_path = "output/scratch_dsl_script.json"
    metadata_path = "config/project_metadata.json"

    print("="*60)
    print("Canonical DSL v1.1 Validation Script")
    print("="*60)

    # Load files
    try:
        dsl = load_json(dsl_path)
        print(f"[OK] Loaded DSL from {dsl_path}")
    except Exception as e:
        print(f"[ERROR] Failed to load DSL: {e}")
        sys.exit(1)

    try:
        metadata = load_json(metadata_path)
        print(f"[OK] Loaded metadata from {metadata_path}")
    except Exception as e:
        print(f"[ERROR] Failed to load metadata: {e}")
        sys.exit(1)

    all_errors = []
    all_warnings = []

    # 1. Validate top-level structure
    print("\n[1/4] Validating top-level structure...")
    struct_errors = validate_structure(dsl)
    if struct_errors:
        all_errors.extend(struct_errors)
        for err in struct_errors:
            print(f"  [FAIL] {err}")
    else:
        print("  [PASS] Structure is valid")

    # 2. Validate script objects
    print("\n[2/4] Validating script objects...")
    all_hat_ids = set()
    if "scripts" in dsl:
        for i, script in enumerate(dsl["scripts"]):
            script_errors = validate_script_object(script, i, all_hat_ids)
            if script_errors:
                all_errors.extend(script_errors)
                for err in script_errors:
                    print(f"  [FAIL] {err}")
            else:
                print(f"  [PASS] Script[{i}] ({script.get('hatId', 'unnamed')})")

    # 3. Validate opcode formatting
    print("\n[3/4] Checking opcode formatting...")
    opcode_check_passed = True
    def check_opcodes(obj):
        nonlocal opcode_check_passed
        if isinstance(obj, dict):
            opcode = obj.get("opcode", "")
            if opcode and not OPCODE_PATTERN.match(opcode):
                all_errors.append(f"Opcode '{opcode}' doesn't match lowercase-with-underscore pattern")
                opcode_check_passed = False
            for value in obj.values():
                check_opcodes(value)
        elif isinstance(obj, list):
            for item in obj:
                check_opcodes(item)
    check_opcodes(dsl)
    if opcode_check_passed:
        print("  [PASS] All opcodes match expected format")
    else:
        print("  [FAIL] Some opcodes have invalid format")

    # 4. Cross-reference variable names
    print("\n[4/4] Cross-referencing variable names...")
    var_errors, var_warnings = validate_variable_names(dsl, metadata.get("variables", []))
    all_errors.extend(var_errors)
    all_warnings.extend(var_warnings)

    if var_errors:
        for err in var_errors:
            print(f"  [FAIL] {err}")
    if var_warnings:
        for warn in var_warnings:
            print(f"  [WARN] {warn}")
    if not var_errors and not var_warnings:
        print("  [PASS] All variable names are valid")

    # Summary
    print("\n" + "="*60)
    print("VALIDATION SUMMARY")
    print("="*60)
    print(f"Total Errors: {len(all_errors)}")
    print(f"Total Warnings: {len(all_warnings)}")

    if all_errors:
        print("\nErrors:")
        for err in all_errors:
            print(f"  - {err}")

    if all_warnings:
        print("\nWarnings:")
        for warn in all_warnings:
            print(f"  - {warn}")

    if all_errors:
        print("\n[RESULT] VALIDATION FAILED")
        sys.exit(1)
    else:
        print("\n[RESULT] VALIDATION PASSED")
        sys.exit(0)

if __name__ == "__main__":
    main()
